[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en" class="scroll-smooth">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <meta name="description" content="Global Aid Alliance — A humanitarian nonprofit dedicated to disaster relief and community resilience worldwide.">
  <title>Global Aid Alliance — Together We Respond</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800;900&display=swap" rel="stylesheet">
  <script src="https://cdn.tailwindcss.com"></script>
  <script src="https://unpkg.com/lucide@latest/dist/umd/lucide.min.js"></script>
  <script>
    tailwind.config = {
      theme: {
        extend: {
          colors: {
            brand: { red: '#C41E3A', navy: '#1B3A5C', 'red-dark': '#A01830', 'navy-light': '#234B6E' },
            warm: { gray: '#F7F5F4', 'gray-dark': '#E8E5E2' }
          },
          fontFamily: { sans: ['Inter', 'system-ui', 'sans-serif'] }
        }
      }
    }
  </script>
  <style>
    :root {
      --red: #C41E3A;
      --red-dark: #A01830;
      --navy: #1B3A5C;
      --navy-light: #234B6E;
      --white: #FFFFFF;
      --gray-50: #FAFAFA;
      --gray-100: #F5F5F5;
      --gray-200: #E5E5E5;
      --gray-600: #666666;
      --gray-900: #1A1A1A;
    }

    *, *::before, *::after { box-sizing: border-box; }
    body { margin: 0; -webkit-font-smoothing: antialiased; -moz-osx-font-smoothing: grayscale; }

    /* --- Animations --- */
    @keyframes fadeInUp {
      from { opacity: 0; transform: translateY(30px); }
      to { opacity: 1; transform: translateY(0); }
    }
    @keyframes fadeIn {
      from { opacity: 0; }
      to { opacity: 1; }
    }
    @keyframes slideInRight {
      from { opacity: 0; transform: translateX(40px); }
      to { opacity: 1; transform: translateX(0); }
    }
    @keyframes countUp {
      from { opacity: 0; transform: translateY(20px); }
      to { opacity: 1; transform: translateY(0); }
    }
    @keyframes pulse-ring {
      0% { box-shadow: 0 0 0 0 rgba(196,30,58,0.4); }
      70% { box-shadow: 0 0 0 15px rgba(196,30,58,0); }
      100% { box-shadow: 0 0 0 0 rgba(196,30,58,0); }
    }

    .animate-fade-in-up { animation: fadeInUp 0.6s ease-out forwards; }
    .animate-fade-in { animation: fadeIn 0.5s ease-out forwards; }
    .delay-100 { animation-delay: 0.1s; }
    .delay-200 { animation-delay: 0.2s; }
    .delay-300 { animation-delay: 0.3s; }
    .delay-400 { animation-delay: 0.4s; }
    .delay-500 { animation-delay: 0.5s; }

    /* --- Hero --- */
    .hero-section {
      background: linear-gradient(135deg, #C41E3A 0%, #8B1228 50%, #1B3A5C 100%);
      position: relative;
      overflow: hidden;
    }
    .hero-section::before {
      content: '';
      position: absolute; inset: 0;
      background: url('data:image/svg+xml,<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1440 320"><path fill="rgba(255,255,255,0.04)" d="M0,160L48,176C96,192,192,224,288,213.3C384,203,480,149,576,138.7C672,128,768,160,864,181.3C960,203,1056,213,1152,197.3C1248,181,1344,139,1392,117.3L1440,96L1440,320L1392,320C1344,320,1248,320,1152,320C1056,320,960,320,864,320C768,320,672,320,576,320C480,320,384,320,288,320C192,320,96,320,48,320L0,320Z"/></svg>') bottom no-repeat;
      background-size: cover;
      pointer-events: none;
    }

    /* --- Stats Counter --- */
    .stat-number { font-variant-numeric: tabular-nums; }
    .stat-card {
      transition: transform 0.3s ease, box-shadow 0.3s ease;
    }
    .stat-card:hover {
      transform: translateY(-4px);
      box-shadow: 0 12px 40px rgba(0,0,0,0.15);
    }

    /* --- Accordion --- */
    .accordion-trigger { cursor: pointer; }
    .accordion-content {
      display: grid;
      grid-template-rows: 0fr;
      transition: grid-template-rows 0.35s ease-out;
    }
    .accordion-content.open {
      grid-template-rows: 1fr;
    }
    .accordion-inner { overflow: hidden; }
    .accordion-icon { transition: transform 0.35s ease; }
    .accordion-trigger[aria-expanded="true"] .accordion-icon {
      transform: rotate(45deg);
    }

    /* --- Carousel --- */
    .carousel-track {
      display: flex;
      transition: transform 0.45s cubic-bezier(0.25, 0.46, 0.45, 0.94);
    }
    .carousel-slide { flex: 0 0 100%; }
    @media (min-width: 768px) { .carousel-slide { flex: 0 0 50%; } }
    @media (min-width: 1024px) { .carousel-slide { flex: 0 0 33.333%; } }

    /* --- Modal --- */
    .modal-overlay {
      position: fixed; inset: 0; z-index: 1000;
      background: rgba(0,0,0,0.6);
      backdrop-filter: blur(4px);
      display: flex; align-items: center; justify-content: center;
      padding: 1rem;
      opacity: 0; visibility: hidden;
      transition: opacity 0.3s ease, visibility 0.3s ease;
    }
    .modal-overlay.active { opacity: 1; visibility: visible; }
    .modal-panel {
      background: white; border-radius: 1rem;
      max-width: 560px; width: 100%; max-height: 90vh;
      overflow-y: auto;
      transform: translateY(20px) scale(0.97);
      transition: transform 0.35s cubic-bezier(0.25, 0.46, 0.45, 0.94);
      box-shadow: 0 25px 60px rgba(0,0,0,0.25);
    }
    .modal-overlay.active .modal-panel {
      transform: translateY(0) scale(1);
    }
    .amount-option {
      cursor: pointer;
      transition: all 0.2s ease;
      border: 2px solid #E5E5E5;
      border-radius: 0.75rem;
      padding: 1rem;
      text-align: center;
    }
    .amount-option:hover { border-color: #C41E3A; background: #FFF5F5; }
    .amount-option.selected {
      border-color: #C41E3A;
      background: #C41E3A;
      color: white;
    }
    .amount-option.selected .impact-text { color: rgba(255,255,255,0.85); }
    .impact-text { color: #666; font-size: 0.8rem; margin-top: 0.25rem; }

    /* --- Mobile Nav Drawer --- */
    .mobile-drawer {
      position: fixed; inset: 0; z-index: 900;
      background: rgba(0,0,0,0.5);
      opacity: 0; visibility: hidden;
      transition: opacity 0.3s ease, visibility 0.3s ease;
    }
    .mobile-drawer.active { opacity: 1; visibility: visible; }
    .mobile-drawer-panel {
      position: absolute; top: 0; right: 0; bottom: 0;
      width: min(300px, 80vw);
      background: white;
      transform: translateX(100%);
      transition: transform 0.35s cubic-bezier(0.25, 0.46, 0.45, 0.94);
      display: flex; flex-direction: column;
    }
    .mobile-drawer.active .mobile-drawer-panel {
      transform: translateX(0);
    }

    /* --- Button Styles --- */
    .btn-primary {
      display: inline-flex; align-items: center; justify-content: center;
      padding: 0.75rem 2rem;
      background: #C41E3A; color: white;
      font-weight: 600; font-size: 1rem;
      border: none; border-radius: 0.5rem;
      cursor: pointer;
      transition: all 0.2s ease;
      text-decoration: none;
    }
    .btn-primary:hover { background: #A01830; transform: translateY(-1px); box-shadow: 0 4px 12px rgba(196,30,58,0.35); }
    .btn-primary:active { transform: translateY(0); }
    .btn-secondary {
      display: inline-flex; align-items: center; justify-content: center;
      padding: 0.75rem 2rem;
      background: transparent; color: white;
      font-weight: 600; font-size: 1rem;
      border: 2px solid rgba(255,255,255,0.8); border-radius: 0.5rem;
      cursor: pointer;
      transition: all 0.2s ease;
      text-decoration: none;
    }
    .btn-secondary:hover { background: rgba(255,255,255,0.1); border-color: white; }
    .btn-outline {
      display: inline-flex; align-items: center; justify-content: center;
      padding: 0.6rem 1.5rem;
      background: transparent; color: #C41E3A;
      font-weight: 600; font-size: 0.9rem;
      border: 2px solid #C41E3A; border-radius: 0.5rem;
      cursor: pointer;
      transition: all 0.2s ease;
      text-decoration: none;
    }
    .btn-outline:hover { background: #C41E3A; color: white; }

    /* --- Header --- */
    .site-header {
      position: sticky; top: 0; z-index: 500;
      background: rgba(255,255,255,0.95);
      backdrop-filter: blur(10px);
      border-bottom: 1px solid #E5E5E5;
    }
    .site-header.scrolled {
      box-shadow: 0 1px 8px rgba(0,0,0,0.08);
    }

    /* --- Section Styles --- */
    .section-title {
      font-size: clamp(1.75rem, 4vw, 2.5rem);
      font-weight: 800;
      line-height: 1.15;
      color: #1A1A1A;
    }
    .section-subtitle {
      font-size: 1.125rem;
      color: #666;
      line-height: 1.7;
      max-width: 650px;
    }

    /* --- Card hover --- */
    .involve-card {
      transition: all 0.3s ease;
    }
    .involve-card:hover {
      transform: translateY(-4px);
      box-shadow: 0 12px 32px rgba(0,0,0,0.08);
    }

    /* --- Scroll-observed --- */
    .reveal {
      opacity: 0;
      transform: translateY(30px);
      transition: opacity 0.6s ease-out, transform 0.6s ease-out;
    }
    .reveal.visible {
      opacity: 1;
      transform: translateY(0);
    }

    /* --- Focus visible --- */
    :focus-visible {
      outline: 2px solid #C41E3A;
      outline-offset: 2px;
    }

    /* --- News cards --- */
    .news-card {
      background: white;
      border-radius: 0.75rem;
      padding: 1.5rem;
      transition: all 0.3s ease;
      height: 100%;
    }
    .news-card:hover {
      box-shadow: 0 8px 24px rgba(0,0,0,0.06);
    }

    /* Hide mobile nav on desktop */
    .hamburger-btn { display: none; }
    @media (max-width: 1023px) {
      .hamburger-btn { display: flex; }
      .desktop-nav { display: none; }
      .desktop-utility { display: none; }
    }
  </style>
</head>
<body class="font-sans text-gray-900 bg-white">

  <!-- ============ HEADER ============ -->
  <header class="site-header" id="siteHeader" role="banner">
    <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
      <div class="flex items-center justify-between h-16 lg:h-18">
        <!-- Logo -->
        <a href="#" class="flex items-center gap-2 no-underline" aria-label="Global Aid Alliance Home">
          <span class="text-brand-red font-extrabold text-xl lg:text-2xl tracking-tight">Global Aid <span class="text-brand-navy">Alliance</span></span>
        </a>

        <!-- Desktop Nav -->
        <nav class="desktop-nav flex items-center gap-1" aria-label="Main navigation">
          <a href="#mission" class="px-3 py-2 text-sm font-medium text-gray-700 hover:text-brand-red transition-colors rounded-md">About Us</a>
          <a href="#programs" class="px-3 py-2 text-sm font-medium text-gray-700 hover:text-brand-red transition-colors rounded-md">Disaster Relief</a>
          <a href="#programs" class="px-3 py-2 text-sm font-medium text-gray-700 hover:text-brand-red transition-colors rounded-md">Programs &amp; Services</a>
          <a href="#get-involved" class="px-3 py-2 text-sm font-medium text-gray-700 hover:text-brand-red transition-colors rounded-md">Volunteer</a>
          <a href="#footer" class="px-3 py-2 text-sm font-medium text-gray-700 hover:text-brand-red transition-colors rounded-md">Find Local Chapter</a>
          <a href="#" class="btn-primary text-sm !py-2 !px-5 ml-3 open-donate" data-tracking="header">Donate</a>
        </nav>

        <!-- Desktop Utility -->
        <div class="desktop-utility flex items-center gap-3 text-xs text-gray-500">
          <a href="#" class="hover:text-brand-red transition-colors">Sign In</a>
          <span class="text-gray-300">|</span>
          <a href="#" class="hover:text-brand-red transition-colors">Contact Us</a>
          <span class="text-gray-300">|</span>
          <a href="#" class="hover:text-brand-red transition-colors">Español</a>
        </div>

        <!-- Hamburger (mobile) -->
        <button class="hamburger-btn items-center justify-center w-10 h-10 rounded-md text-gray-700 hover:bg-gray-100 transition-colors" id="hamburgerBtn" aria-label="Open menu" aria-expanded="false">
          <i data-lucide="menu" class="w-6 h-6"></i>
        </button>
      </div>
    </div>
  </header>

  <!-- Mobile Drawer -->
  <div class="mobile-drawer" id="mobileDrawer" aria-hidden="true">
    <div class="mobile-drawer-panel" id="mobileDrawerPanel">
      <div class="flex items-center justify-between p-4 border-b border-gray-200">
        <span class="font-bold text-brand-red">Menu</span>
        <button class="flex items-center justify-center w-10 h-10 rounded-md text-gray-700 hover:bg-gray-100 transition-colors" id="closeDrawerBtn" aria-label="Close menu">
          <i data-lucide="x" class="w-6 h-6"></i>
        </button>
      </div>
      <nav class="flex flex-col p-4 gap-1 flex-1" aria-label="Mobile navigation">
        <a href="#mission" class="px-3 py-3 text-base font-medium text-gray-800 hover:text-brand-red hover:bg-red-50 rounded-md transition-colors mobile-nav-link">About Us</a>
        <a href="#programs" class="px-3 py-3 text-base font-medium text-gray-800 hover:text-brand-red hover:bg-red-50 rounded-md transition-colors mobile-nav-link">Disaster Relief</a>
        <a href="#programs" class="px-3 py-3 text-base font-medium text-gray-800 hover:text-brand-red hover:bg-red-50 rounded-md transition-colors mobile-nav-link">Programs &amp; Services</a>
        <a href="#get-involved" class="px-3 py-3 text-base font-medium text-gray-800 hover:text-brand-red hover:bg-red-50 rounded-md transition-colors mobile-nav-link">Volunteer</a>
        <a href="#footer" class="px-3 py-3 text-base font-medium text-gray-800 hover:text-brand-red hover:bg-red-50 rounded-md transition-colors mobile-nav-link">Find Local Chapter</a>
        <hr class="my-2 border-gray-200">
        <a href="#" class="px-3 py-3 text-sm text-gray-500 hover:text-brand-red transition-colors">Sign In</a>
        <a href="#" class="px-3 py-3 text-sm text-gray-500 hover:text-brand-red transition-colors">Contact Us</a>
        <a href="#" class="px-3 py-3 text-sm text-gray-500 hover:text-brand-red transition-colors">Español</a>
        <div class="mt-4 px-3">
          <a href="#" class="btn-primary w-full text-center open-donate" data-tracking="mobile-nav">Donate</a>
        </div>
      </nav>
    </div>
  </div>

  <!-- ============ HERO ============ -->
  <section class="hero-section text-white relative" id="hero" aria-labelledby="hero-heading">
    <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-20 md:py-28 lg:py-36 relative z-10">
      <div class="max-w-3xl">
        <h1 id="hero-heading" class="text-4xl sm:text-5xl lg:text-6xl font-extrabold leading-tight tracking-tight mb-6 animate-fade-in-up">
          When Disaster Strikes, We're There
        </h1>
        <p class="text-lg sm:text-xl lg:text-2xl opacity-90 leading-relaxed mb-10 animate-fade-in-up delay-200" style="text-wrap: pretty;">
          From hurricanes and wildfires to global health emergencies, Global Aid Alliance delivers immediate relief and long-term recovery support to communities in crisis.
        </p>
        <div class="flex flex-wrap gap-4 animate-fade-in-up delay-400">
          <a href="#" class="btn-primary !bg-white !text-brand-red hover:!bg-gray-100 !text-lg !py-3.5 !px-8 open-donate" data-tracking="hero">
            Donate Now
            <i data-lucide="heart" class="w-5 h-5 ml-2"></i>
          </a>
          <a href="#get-involved" class="btn-secondary !text-lg !py-3.5 !px-8">
            Become a Volunteer
            <i data-lucide="arrow-right" class="w-5 h-5 ml-2"></i>
          </a>
        </div>
      </div>
    </div>
  </section>

  <!-- ============ MISSION ============ -->
  <section class="py-16 md:py-24 bg-white" id="mission" aria-labelledby="mission-heading">
    <div class="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
      <h2 id="mission-heading" class="section-title mb-6 reveal">Our Mission</h2>
      <p class="text-xl md:text-2xl font-semibold text-brand-navy leading-relaxed mb-8 reveal reveal" style="text-wrap: pretty;">
        Global Aid Alliance prevents and alleviates human suffering in the face of emergencies by mobilizing the power of volunteers and the generosity of donors.
      </p>
      <p class="section-subtitle mx-auto reveal" style="text-wrap: pretty;">
        We are guided by the fundamental principles of humanity, impartiality, and neutrality. Every day, our teams work across borders and boundaries to ensure that help reaches those who need it most — regardless of race, religion, nationality, or political affiliation. From the first hours of a disaster to the years of recovery that follow, we stand with affected communities every step of the way.
      </p>
    </div>
  </section>

  <!-- ============ IMPACT STATISTICS ============ -->
  <section class="py-16 md:py-24 bg-brand-navy text-white relative overflow-hidden" id="impact" aria-labelledby="impact-heading">
    <div class="absolute inset-0 opacity-5">
      <div class="absolute top-10 left-10 w-64 h-64 rounded-full bg-white"></div>
      <div class="absolute bottom-10 right-10 w-96 h-96 rounded-full bg-white"></div>
    </div>
    <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative z-10">
      <h2 id="impact-heading" class="text-3xl lg:text-4xl font-extrabold text-center mb-4 reveal">Our Impact</h2>
      <p class="text-center text-white/70 max-w-xl mx-auto mb-14 reveal" style="text-wrap: pretty;">
        These figures represent real lives changed — families sheltered, blood delivered, communities rebuilt.
      </p>
      <div class="grid grid-cols-2 lg:grid-cols-4 gap-6 md:gap-8">
        <div class="stat-card bg-white/10 backdrop-blur-sm rounded-xl p-6 md:p-8 text-center border border-white/10 reveal">
          <div class="text-3xl sm:text-4xl lg:text-5xl font-extrabold stat-number mb-2" data-count="12" data-suffix="M+" data-decimals="0">0</div>
          <p class="text-white/80 text-sm sm:text-base font-medium">people assisted annually</p>
        </div>
        <div class="stat-card bg-white/10 backdrop-blur-sm rounded-xl p-6 md:p-8 text-center border border-white/10 reveal">
          <div class="text-3xl sm:text-4xl lg:text-5xl font-extrabold stat-number mb-2" data-count="50000" data-suffix="" data-decimals="0" data-format="comma">0</div>
          <p class="text-white/80 text-sm sm:text-base font-medium">volunteers active worldwide</p>
        </div>
        <div class="stat-card bg-white/10 backdrop-blur-sm rounded-xl p-6 md:p-8 text-center border border-white/10 reveal">
          <div class="text-3xl sm:text-4xl lg:text-5xl font-extrabold stat-number mb-2" data-count="190" data-suffix="" data-decimals="0">0</div>
          <p class="text-white/80 text-sm sm:text-base font-medium">countries where we've provided aid</p>
        </div>
        <div class="stat-card bg-white/10 backdrop-blur-sm rounded-xl p-6 md:p-8 text-center border border-white/10 reveal">
          <div class="text-3xl sm:text-4xl lg:text-5xl font-extrabold stat-number mb-2" data-count="850" data-suffix="M" data-decimals="0" data-prefix="$">0</div>
          <p class="text-white/80 text-sm sm:text-base font-medium">raised in the last fiscal year</p>
        </div>
      </div>
    </div>
  </section>

  <!-- ============ PROGRAMS (Accordion) ============ -->
  <section class="py-16 md:py-24 bg-warm-gray" id="programs" aria-labelledby="programs-heading">
    <div class="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8">
      <h2 id="programs-heading" class="section-title text-center mb-4 reveal">Programs &amp; Services</h2>
      <p class="section-subtitle text-center mx-auto mb-12 reveal">Our core programs deliver immediate relief and long-term resilience to communities worldwide.</p>

      <div class="space-y-3" role="region" aria-label="Programs accordion">
        <!-- Program 1 -->
        <div class="bg-white rounded-xl border border-gray-200 overflow-hidden reveal">
          <button class="accordion-trigger w-full flex items-center justify-between p-5 md:p-6 text-left hover:bg-gray-50 transition-colors" aria-expanded="false" aria-controls="panel-disaster">
            <div class="flex items-center gap-4">
              <span class="flex items-center justify-center w-10 h-10 rounded-lg bg-red-50 text-brand-red shrink-0"><i data-lucide="umbrella" class="w-5 h-5"></i></span>
              <span class="font-semibold text-lg">Disaster Relief</span>
            </div>
            <span class="accordion-icon flex items-center justify-center w-8 h-8 rounded-full bg-gray-100 shrink-0 transition-colors"><i data-lucide="plus" class="w-5 h-5 text-gray-600"></i></span>
          </button>
          <div class="accordion-content" id="panel-disaster" role="region">
            <div class="accordion-inner">
              <div class="px-5 md:px-6 pb-5 md:pb-6 text-gray-600 leading-relaxed">
                Rapid deployment of emergency shelter, food, water, and medical supplies to communities affected by natural disasters and conflict. Our response teams are on the ground within 24 hours.
              </div>
            </div>
          </div>
        </div>

        <!-- Program 2 -->
        <div class="bg-white rounded-xl border border-gray-200 overflow-hidden reveal">
          <button class="accordion-trigger w-full flex items-center justify-between p-5 md:p-6 text-left hover:bg-gray-50 transition-colors" aria-expanded="false" aria-controls="panel-blood">
            <div class="flex items-center gap-4">
              <span class="flex items-center justify-center w-10 h-10 rounded-lg bg-red-50 text-brand-red shrink-0"><i data-lucide="droplet" class="w-5 h-5"></i></span>
              <span class="font-semibold text-lg">Blood Donation</span>
            </div>
            <span class="accordion-icon flex items-center justify-center w-8 h-8 rounded-full bg-gray-100 shrink-0 transition-colors"><i data-lucide="plus" class="w-5 h-5 text-gray-600"></i></span>
          </button>
          <div class="accordion-content" id="panel-blood" role="region">
            <div class="accordion-inner">
              <div class="px-5 md:px-6 pb-5 md:pb-6 text-gray-600 leading-relaxed">
                Operating one of the largest blood collection networks, we supply approximately 40% of the nation's blood and blood products to hospitals and medical facilities.
              </div>
            </div>
          </div>
        </div>

        <!-- Program 3 -->
        <div class="bg-white rounded-xl border border-gray-200 overflow-hidden reveal">
          <button class="accordion-trigger w-full flex items-center justify-between p-5 md:p-6 text-left hover:bg-gray-50 transition-colors" aria-expanded="false" aria-controls="panel-prep">
