  <script>
    // =================== ICONS ===================
    lucide.createIcons();

    // =================== MOBILE DRAWER ===================
    const drawer = document.getElementById('mobileDrawer');
    const hamburgerBtn = document.getElementById('hamburgerBtn');
    const closeDrawerBtn = document.getElementById('closeDrawerBtn');
    const mobileNavLinks = document.querySelectorAll('.mobile-nav-link');

    function openDrawer() {
      drawer.classList.add('active');
      drawer.setAttribute('aria-hidden', 'false');
      hamburgerBtn.setAttribute('aria-expanded', 'true');
      document.body.style.overflow = 'hidden';
      setTimeout(() => {
        const firstLink = drawer.querySelector('.mobile-nav-link');
        if (firstLink) firstLink.focus();
      }, 100);
    }

    function closeDrawer() {
      drawer.classList.remove('active');
      drawer.setAttribute('aria-hidden', 'true');
      hamburgerBtn.setAttribute('aria-expanded', 'false');
      document.body.style.overflow = '';
      hamburgerBtn.focus();
    }

    hamburgerBtn.addEventListener('click', openDrawer);
    closeDrawerBtn.addEventListener('click', closeDrawer);
    drawer.addEventListener('click', function(e) {
      if (e.target === drawer) closeDrawer();
    });
    mobileNavLinks.forEach(link => link.addEventListener('click', closeDrawer));
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape' && drawer.classList.contains('active')) closeDrawer();
    });

    // =================== DONATION MODAL ===================
    const modal = document.getElementById('donationModal');
    const closeModalBtn = document.getElementById('closeModal');
    const cancelBtn = document.getElementById('cancelDonation');
    const submitBtn = document.getElementById('submitDonation');
    const amountOptions = document.querySelectorAll('.amount-option');
    const customAmountWrap = document.getElementById('customAmountWrap');
    const customAmountInput = document.getElementById('customAmount');
    const selectedImpact = document.getElementById('selectedImpact');
    const selectedImpactSpan = selectedImpact.querySelector('span');
    let selectedAmount = null;

    function openModal() {
      modal.classList.add('active');
      modal.setAttribute('aria-hidden', 'false');
      document.body.style.overflow = 'hidden';
      setTimeout(() => {
        closeModalBtn.focus();
      }, 100);
    }

    function closeModalFn() {
      modal.classList.remove('active');
      modal.setAttribute('aria-hidden', 'true');
      document.body.style.overflow = '';
    }

    document.querySelectorAll('.open-donate').forEach(btn => {
      btn.addEventListener('click', function(e) {
        e.preventDefault();
        openModal();
      });
    });

    closeModalBtn.addEventListener('click', closeModalFn);
    cancelBtn.addEventListener('click', closeModalFn);
    modal.addEventListener('click', function(e) {
      if (e.target === modal) closeModalFn();
    });
    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape' && modal.classList.contains('active')) closeModalFn();
    });

    amountOptions.forEach(option => {
      option.addEventListener('click', function() {
        amountOptions.forEach(o => o.classList.remove('selected'));
        this.classList.add('selected');
        selectedAmount = this.dataset.amount;

        if (selectedAmount === 'custom') {
          customAmountWrap.classList.remove('hidden');
          selectedImpact.classList.add('hidden');
          setTimeout(() => customAmountInput.focus(), 50);
        } else {
          customAmountWrap.classList.add('hidden');
          selectedImpact.classList.remove('hidden');
          selectedImpactSpan.textContent = this.dataset.impact;
        }
      });
    });

    customAmountInput.addEventListener('input', function() {
      const val = parseInt(this.value);
      if (val && val > 0) {
        selectedImpact.classList.remove('hidden');
        selectedImpactSpan.textContent = '$' + val + ' — Every dollar counts toward saving lives';
      } else {
        selectedImpact.classList.add('hidden');
      }
    });

    submitBtn.addEventListener('click', function() {
      let amount = selectedAmount;
